const pages = $input.all().map(item => item.json).filter(page => page.status === "success" && page.output_format === "markdown" && typeof page.content === "string" && page.content.trim().length > 0);
if (pages.length === 0) throw new Error("Extractor returned no successful Markdown pages.");
return pages.map(page => ({json: {
  sourceUrl: page.url,
  title: page.title || "",
  content: "Source URL: " + page.url + "\nPage title: " + (page.title || "") + "\n\n" + page.content
}}));

const items = $input.all();
const normalizedSources = $("Normalize Markdown pages").all();
const normalizeUrl = value => {
  if (typeof value !== "string") return null;
  try {
    const url = new URL(value.trim());
    if (url.protocol !== "http:" && url.protocol !== "https:") return null;
    url.hash = "";
    if (url.pathname.length > 1) url.pathname = url.pathname.replace(/\/+$/, "");
    const result = url.toString();
    return url.pathname === "/" ? result : result.replace(/\/$/, "");
  } catch {
    return null;
  }
};
const expectedUrls = new Set(normalizedSources
  .map(item => normalizeUrl(item.json?.sourceUrl))
  .filter(Boolean));
if (items.length === 0) throw new Error("Vector retrieval returned no documents.");
if (expectedUrls.size === 0) throw new Error("No source URLs were available from this execution.");
const sourceUrlKeys = new Set(["sourceurl", "source_url", "url"]);
const retrievedUrls = new Set();
const collectSourceUrls = (value, key = "", depth = 0) => {
  if (depth > 20 || value === null || value === undefined) return;
  if (typeof value === "string") {
    if (sourceUrlKeys.has(key.toLowerCase())) {
      const normalized = normalizeUrl(value);
      if (normalized) retrievedUrls.add(normalized);
    }
    for (const match of value.matchAll(/(?:^|\n)\s*Source URL:\s*(https?:\/\/[^\s"'<>]+)/gim)) {
      const normalized = normalizeUrl(match[1].replace(/[),.;]+$/, ""));
      if (normalized) retrievedUrls.add(normalized);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectSourceUrls(item, key, depth + 1);
    return;
  }
  if (typeof value === "object") {
    for (const [childKey, childValue] of Object.entries(value)) {
      collectSourceUrls(childValue, childKey, depth + 1);
    }
  }
};
for (const item of items) collectSourceUrls(item.json || item);
const unexpectedUrls = [...retrievedUrls].filter(url => !expectedUrls.has(url));
if (unexpectedUrls.length > 0) {
  throw new Error("Vector retrieval returned a source URL outside this execution's normalized records.");
}
const matched = retrievedUrls.size > 0;
return [{json:{
  retrievalOk:true,
  retrievedDocuments:items.length,
  sourceVerification:matched ? "matched" : "unavailable",
  matchedSourceUrls:retrievedUrls.size,
  expectedSourceUrls:expectedUrls.size
}}];
